// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        vm.deal(address(c), amount);

        uint256 recipientBalanceBefore = recipient.balance;

        c.withdrawAll(recipient);

        assertTrue(recipient.balance - recipientBalanceBefore == amount);
    }
}

